import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var objects = Array.from({ length: 148 }, function (_, i) { return { id: i + 1, name: 'Объект ' + String(i + 1).padStart(2, '0') }; });
function Example(props) {
    var page = React.useState(0), size = React.useState(5), data = props.empty ? [] : objects;
    var visible = data.slice(page[0] * size[0], (page[0] + 1) * size[0]);
    return <div className={props.compact ? 'demo-stack narrow' : 'demo-stack'}>
    <div aria-live={'polite'} aria-atomic={'true'}>
    {visible.length ? <ul className={'list'}>
    {visible.map(function (item) {
                return <li key={item.id}>
    {item.name}
    </li>;
            })}
    </ul> : <p className={'cap'}>
    {'Ничего не найдено'}
    </p>}
    </div>
    <S.DsPagination page={page[0]} pageSize={size[0]} length={data.length} compact={props.compact} pageSizeOptions={[5, 10, 25]} onPageChange={page[1]} ariaLabel={props.title} onPageSizeChange={props.compact ? undefined : function (next) { size[1](next); page[1](0); }}/>
    </div>;
}
function App() {
    return <div className="dspagination-example">
    <style>{exampleStyles}</style>
    <Example title={'Страницы и количество строк'}/>
    </div>;
}

const exampleStyles = ".dspagination-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dspagination-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dspagination-example p{margin:0}\n.dspagination-example .list{list-style:none;padding:0;margin:0}\n.dspagination-example .list li{padding:8px 0;border-bottom:1px solid var(--ds-divider)}\n.dspagination-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}\n.dspagination-example .narrow{width:100%;max-width:280px}";

export { App as Example };

